function getGuide(lang){ return GUIDE_I18N[lang] || GUIDE_I18N.EN; }
const guideMatch = (e,q) => {
  const n = q.trim().toLowerCase();
  if (!n) return true;
  return e.title.toLowerCase().includes(n) || e.keywords.toLowerCase().includes(n) || e.body.toLowerCase().includes(n);
};

// Task-flow ordering + section grouping for the guide, keyed by entry id so it
// applies across all languages without touching the per-language arrays. The
// section label (translated via t()) is shown above the FIRST entry of each
// group when not searching. org = display order; sec = section key.
const GUIDE_ORDER = [
  // Getting started
  ['overview','start'],['start-here',null],['modes',null],['style',null],['random',null],
  // Sources
  ['moods','sources'],['compose',null],['mobile-keys',null],['scale-snap',null],['mic',null],['midi',null],['audio',null],['score',null],['image',null],
  // While playing
  ['playback','playing'],['speed',null],['loop',null],['mute',null],['morph',null],['vary',null],
  // Save & share
  ['print','output'],['record',null],
  // More
  ['demo','more'],['clear',null],['micvol',null],['troubleshoot',null],
];
const GUIDE_POS = Object.fromEntries(GUIDE_ORDER.map(([id],i)=>[id,i]));
const GUIDE_SEC = Object.fromEntries(GUIDE_ORDER.filter(([,s])=>s).map(([id,s])=>[id,s]));
// Order a language's guide entries by GUIDE_POS; unknown ids fall to the end in
// their original order (defensive — every current id is mapped).
function orderedGuide(lang){
  const list = getGuide(lang);
  return [...list].sort((a,b)=>{
    const pa = GUIDE_POS[a.id] ?? 999, pb = GUIDE_POS[b.id] ?? 999;
    return pa - pb;
  });
}


// Reverse lookup: any localized mood word (EN/DE/FR/ES/SK) → canonical English
// key. Built once from every language's moodNames table, so typing a mood in
// ANY of the 5 languages resolves to the same crafted song. The first language
// to claim a word wins (EN first), so existing keys stay stable on collisions.
const MOOD_ALIASES_EXTRA = {'nadšená':'excited','optimistická':'hopeful','zasnená':'dreamy','zamilovaná':'love','hrejivá':'warm','roztúžená':'yearning','zlostná':'furious'};
const MOOD_ALIASES = (()=>{
  const map={};
  const langs=['EN','DE','FR','ES','SK'];
  try{
    for(const code of langs){
      const mn = (I18N[code] && I18N[code].moodNames) || null;
      if(!mn) continue;
      for(const key of Object.keys(mn)){
        const word=(mn[key]||'').toLowerCase().trim();
        if(word && !(word in map)) map[word]=key;   // first claim wins
      }
    }
  }catch(_){}
  for(const w in MOOD_ALIASES_EXTRA){ if(!(w in map)) map[w]=MOOD_ALIASES_EXTRA[w]; }
  return map;
})();

function findSong(query) {
  const q = (query||'').toLowerCase().trim();
  // 1) exact canonical key (e.g. 'funny')
  let hit = SONG_LIBRARY.find(s => s.mood === q);
  if(hit) return hit;
  // 2) localized word in any of the 5 languages (e.g. 'veselá' → 'funny')
  const key = MOOD_ALIASES[q];
  if(key){ hit = SONG_LIBRARY.find(s => s.mood === key); if(hit) return hit; }
  return undefined;
}

